	router.PATCH(options.BaseURL+"/dns/zones/:zoneId/records/:recordId", wrapper.UpdateDnsRecord)
	router.GET(options.BaseURL+"/dns/zones/:zoneId/linked", wrapper.ListLinkedRecords)
